package com.company.app.feature.profile.data.repository

import com.company.app.feature.profile.data.datasource.ProfileRemoteDataSource
import com.company.app.feature.profile.domain.repository.IProfileRepository
import com.company.app.feature.profile.domain.usecase.ProfileData

class ProfileRepository(
    private val remoteDataSource: ProfileRemoteDataSource
) : IProfileRepository {

    override suspend fun getProfile(): ProfileData {
        val response = remoteDataSource.fetchProfile()
        return ProfileData(name = response.name, email = response.email, lastLoginAt = response.lastLoginAt)
    }
}

package com.company.app.feature.profile.presentation.viewmodel

import androidx.lifecycle.viewModelScope
import com.company.app.common.base.BaseSharedViewModel
import com.company.app.feature.profile.domain.usecase.GetProfileUseCase
import kotlinx.coroutines.launch

class ProfileViewModel(
    private val getProfileUseCase: GetProfileUseCase
) : BaseSharedViewModel<ProfileViewState, ProfileViewAction, ProfileViewEvent>(
    initialState = ProfileViewState()
) {

    override fun handleEvent(event: ProfileViewEvent) {
        when (event) {
            is ProfileViewEvent.LoadProfile -> loadProfile()
            is ProfileViewEvent.OnEditClicked -> sendAction(ProfileViewAction.NavigateToEdit)
        }
    }

    private fun loadProfile() {
        viewModelScope.launch {
            updateState { it.copy(isLoading = true, error = null) }
            getProfileUseCase.execute(Unit).fold(
                onSuccess = { data -> updateState { it.copy(isLoading = false, name = data.name, email = data.email, lastLoginAt = data.lastLoginAt) } },
                onFailure = { error -> updateState { it.copy(isLoading = false, error = error.message) } }
            )
        }
    }
}

